/** TipTap's canonical empty document; the field treats it as an empty string. */
function normalizeEditorHtml(html: string): string {
  return html === "<p></p>" ? "" : html;
}

// Full StarterKit schema: headings/blockquote/code have no toolbar buttons but stay
// reachable via paste, markdown input rules, and keyboard shortcuts — pasted
// structure is preserved rather than flattened. Links open on click only outside
// the editor (a click while editing should place the cursor, not navigate).
const extensions = [
  StarterKit.configure({
    link: { openOnClick: false },
  }),
];

export function ShadRichTextInput(
  p: RichTextInputProps & {
    /** Test/advanced hook: receives the live TipTap editor instance. */
    editorRef?: MutableRefObject<Editor | null>;
  },
): ReactElement {
  const id = useStableId();
  const aria = fieldAria(id, p, { labelledBy: true });
  const editor = useEditor({
    extensions,
    content: p.value,
    editable: !p.disabled,
    // ProseMirror owns the contenteditable, so the naming has to go through it.
    editorProps: {
      attributes: {
        role: "textbox",
        "aria-multiline": "true",
        ...(aria["aria-labelledby"] !== undefined
          ? { "aria-labelledby": aria["aria-labelledby"] }
          : {}),
        ...(aria["aria-describedby"] !== undefined
          ? { "aria-describedby": aria["aria-describedby"] }
          : {}),
      },
    },
    onUpdate: ({ editor: e }) => p.onChange(normalizeEditorHtml(e.getHTML())),
    ...(p.onBlur ? { onBlur: p.onBlur } : {}),
  });

  useEffect(() => {
    if (p.editorRef) p.editorRef.current = editor ?? null;
  }, [editor, p.editorRef]);

  // Echo guard: push the external value in only when it differs from the editor's
  // own HTML — otherwise every keystroke round-trips and resets the cursor.
  useEffect(() => {
    if (!editor) return;
    if (p.value !== normalizeEditorHtml(editor.getHTML())) {
      editor.commands.setContent(p.value, { emitUpdate: false });
    }
  }, [editor, p.value]);

  useEffect(() => {
    // Second arg suppresses the update event — this is a chrome change, not an edit.
    editor?.setEditable(!p.disabled, false);
  }, [editor, p.disabled]);

  const state = useEditorState({
    editor,
    selector: (ctx) =>
      ctx.editor
        ? {
            bold: ctx.editor.isActive("bold"),
            italic: ctx.editor.isActive("italic"),
            underline: ctx.editor.isActive("underline"),
            strike: ctx.editor.isActive("strike"),
            bulletList: ctx.editor.isActive("bulletList"),
            orderedList: ctx.editor.isActive("orderedList"),
            link: ctx.editor.isActive("link"),
            canUndo: ctx.editor.can().undo(),
            canRedo: ctx.editor.can().redo(),
          }
        : null,
  });

  const [linkOpen, setLinkOpen] = useState(false);
  const [linkDraft, setLinkDraft] = useState("");

  const openLink = (open: boolean): void => {
    if (open) setLinkDraft(String(editor?.getAttributes("link").href ?? ""));
    setLinkOpen(open);
  };
  const applyLink = (): void => {
    const href = linkDraft.trim();
    const chain = editor?.chain().focus().extendMarkRange("link");
    if (href) chain?.setLink({ href }).run();
    else chain?.unsetLink().run();
    setLinkOpen(false);
  };
  const removeLink = (): void => {
    editor?.chain().focus().extendMarkRange("link").unsetLink().run();
    setLinkOpen(false);
  };

  const marks: {
    icon: ReactElement;
    label: string;
    active?: boolean;
    run: () => void;
  }[] = [
    {
      icon: <Bold />,
      label: "Bold",
      active: state?.bold,
      run: () => editor?.chain().focus().toggleBold().run(),
    },
    {
      icon: <Italic />,
      label: "Italic",
      active: state?.italic,
      run: () => editor?.chain().focus().toggleItalic().run(),
    },
    {
      icon: <Underline />,
      label: "Underline",
      active: state?.underline,
      run: () => editor?.chain().focus().toggleUnderline().run(),
    },
    {
      icon: <Strikethrough />,
      label: "Strikethrough",
      active: state?.strike,
      run: () => editor?.chain().focus().toggleStrike().run(),
    },
    {
      icon: <List />,
      label: "Bulleted list",
      active: state?.bulletList,
      run: () => editor?.chain().focus().toggleBulletList().run(),
    },
    {
      icon: <ListOrdered />,
      label: "Numbered list",
      active: state?.orderedList,
      run: () => editor?.chain().focus().toggleOrderedList().run(),
    },
  ];

  return (
    <Chrome {...p} htmlFor={id}>
      <div
        className={cn(
          "rounded-md border border-input bg-transparent shadow-xs",
          "focus-within:ring-1 focus-within:ring-ring",
          p.disabled && "opacity-50",
        )}
      >
        <div
          role="toolbar"
          aria-label="Text formatting"
          className="flex flex-wrap items-center gap-0.5 border-b border-input p-1"
        >
          {marks.map((m) => (
            <Button
              key={m.label}
              type="button"
              variant="ghost"
              size="icon"
              aria-label={m.label}
              aria-pressed={!!m.active}
              disabled={p.disabled}
              className={cn("size-7", m.active && "bg-accent")}
              onClick={m.run}
            >
              {m.icon}
            </Button>
          ))}
          <Popover open={linkOpen} onOpenChange={openLink}>
            <PopoverTrigger asChild>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                aria-label="Link"
                aria-pressed={!!state?.link}
                disabled={p.disabled}
                className={cn("size-7", state?.link && "bg-accent")}
              >
                <Link2 />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="grid w-72 gap-2">
              <Input
                aria-label="Link URL"
                placeholder="https://"
                value={linkDraft}
                onChange={(e) => setLinkDraft(e.target.value)}
              />
              <div className="flex gap-2">
                <Button type="button" size="sm" onClick={applyLink}>
                  Apply
                </Button>
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  onClick={removeLink}
                >
                  Remove
                </Button>
              </div>
            </PopoverContent>
          </Popover>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label="Undo"
            disabled={p.disabled || !state?.canUndo}
            className="size-7"
            onClick={() => editor?.chain().focus().undo().run()}
          >
            <Undo2 />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label="Redo"
            disabled={p.disabled || !state?.canRedo}
            className="size-7"
            onClick={() => editor?.chain().focus().redo().run()}
          >
            <Redo2 />
          </Button>
        </div>
        <EditorContent
          editor={editor}
          className={cn(
            "text-sm",
            "[&_.ProseMirror]:min-h-24 [&_.ProseMirror]:px-3 [&_.ProseMirror]:py-2 [&_.ProseMirror]:outline-none",
            "[&_.ProseMirror_ul]:list-disc [&_.ProseMirror_ul]:pl-5",
            "[&_.ProseMirror_ol]:list-decimal [&_.ProseMirror_ol]:pl-5",
            "[&_.ProseMirror_a]:text-primary [&_.ProseMirror_a]:underline",
          )}
        />
      </div>
    </Chrome>
  );
}

import { useState } from "react";
import type { ReactElement, ReactNode } from "react";
import { Maximize2, Minimize2, X } from "lucide-react";

import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { useDragResize, useResizable } from "@speel/react";
import type {
  DialogProps,
  DrawerProps,
  PopoverProps,
  MenuProps,
} from "@speel/react";

import { iconFor } from "./icons";

const DIALOG_WIDTH = { small: 480, medium: 640, large: 840 } as const;
const DIALOG_HEIGHT = { small: 440, medium: 560, large: 640 } as const;
const DIALOG_MIN = { w: 360, h: 260 };

/** The dialog's size caps (its CSS 96vw x 92vh) and the viewport it must stay inside.
 *  Read at render; empty outside a browser. */
function viewportBounds(): {
  max?: { w: number; h: number };
  bounds?: { w: number; h: number };
} {
  if (typeof window === "undefined") return {};
  const w = window.innerWidth;
  const h = window.innerHeight;
  return {
    max: { w: Math.floor(w * 0.96), h: Math.floor(h * 0.92) },
    bounds: { w, h },
  };
}
const SHEET_WIDTH = { small: 420, medium: 640, large: 880 } as const;

/**
 * A menu, not a popover full of buttons: radix supplies roles, arrow-key navigation, and
 * typeahead, and the checkbox item reserves its indicator gutter so unchecked siblings stay
 * aligned. Sections render as a label plus a separator between runs.
 */
export function ShadMenu(p: MenuProps): ReactElement {
  return (
    <DropdownMenu open={p.open} onOpenChange={p.onOpenChange}>
      <DropdownMenuTrigger asChild>
        <span className="inline-flex">{p.trigger as ReactNode}</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="speel-shadcn">
        {p.sections.map((section, i) => (
          <div key={section.key}>
            {i > 0 ? <DropdownMenuSeparator /> : null}
            {section.title !== undefined ? (
              <DropdownMenuLabel>{section.title}</DropdownMenuLabel>
            ) : null}
            {section.items.map((item) => {
              const Icon =
                item.iconName !== undefined
                  ? iconFor(item.iconName)
                  : undefined;
              const body = (
                <>
                  {Icon ? <Icon className="size-4" /> : null}
                  {item.text}
                </>
              );
              return item.checked !== undefined ? (
                <DropdownMenuCheckboxItem
                  key={item.key}
                  checked={item.checked}
                  disabled={item.disabled}
                  onSelect={() => item.onClick?.()}
                >
                  {body}
                </DropdownMenuCheckboxItem>
              ) : (
                <DropdownMenuItem
                  key={item.key}
                  disabled={item.disabled}
                  onSelect={() => item.onClick?.()}
                >
                  {body}
                </DropdownMenuItem>
              );
            })}
          </div>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export function ShadDialog(p: DialogProps): ReactElement {
  const resizable = p.resizable ?? true;
  const draggable = p.draggable ?? true;
  const showFs = p.fullscreenToggle ?? true;
  const [fullscreen, setFullscreen] = useState(false);
  const presetW = DIALOG_WIDTH[p.size ?? "medium"];
  const presetH = DIALOG_HEIGHT[p.size ?? "medium"];
  const { size, transform, dragHandleProps, resizeHandleProps } = useDragResize(
    {
      min: DIALOG_MIN,
      initial: { w: presetW, h: presetH },
      ...viewportBounds(),
      label: "Resize dialog",
    },
  );

  const width = fullscreen ? "96vw" : `${resizable ? size.w : presetW}px`;
  const height = fullscreen ? "92vh" : `${resizable ? size.h : presetH}px`;

  return (
    <Dialog
      open={p.open}
      onOpenChange={(o) => {
        if (!o && p.blocking) return;
        p.onOpenChange(o);
      }}
    >
      {/* speel-shadcn tag: portaled content escapes the host wrapper, so each portal
          re-applies the class that scopes the skin's base-layer CSS rules. */}
      <DialogContent
        showCloseButton={false}
        aria-describedby={undefined}
        // animate-none: the stock zoom/fade keyframes write `transform` and would
        // clobber the inline centering+drag transform mid-animation.
        // transition-none: the stock `duration-200` sets transition-duration with
        // transition-property at its initial `all`, so every inline width/height/
        // transform write would otherwise start a 200ms implicit transition and
        // drag/resize rubber-bands instead of tracking the pointer.
        className="speel-shadcn flex flex-col gap-0 overflow-hidden p-0 transition-none data-[state=open]:animate-none data-[state=closed]:animate-none"
        style={{
          width,
          height,
          maxWidth: "96vw",
          maxHeight: "92vh",
          // Neutralizes the stock translate-x/y-[-50%] utilities (CSS `translate`
          // property, Safari 15.4+/Chrome 104+); centering lives in `transform`
          // below so the drag offset composes with it.
          translate: "none",
          transform: fullscreen
            ? "translate(-50%, -50%)"
            : `translate(-50%, -50%) ${transform}`,
        }}
        onInteractOutside={(e) => {
          if (p.blocking) e.preventDefault();
        }}
        onEscapeKeyDown={(e) => {
          if (p.blocking) e.preventDefault();
        }}
      >
        {/* Sticky header — doubles as the drag handle (buttons excluded by useDragResize). */}
        <div
          {...(draggable && !fullscreen ? dragHandleProps : {})}
          className={cn(
            "flex flex-none items-center gap-2 border-b px-5 py-3",
            draggable && !fullscreen && "cursor-move touch-none",
          )}
        >
          {/* DialogTitle always rendered for a11y; renders empty string when title is undefined */}
          <DialogTitle className="grow truncate text-lg font-semibold">
            {p.title ?? ""}
          </DialogTitle>
          {showFs ? (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-8"
              aria-label="Toggle fullscreen"
              onClick={() => setFullscreen((f) => !f)}
            >
              {fullscreen ? (
                <Minimize2 className="size-4" />
              ) : (
                <Maximize2 className="size-4" />
              )}
            </Button>
          ) : null}
          {p.blocking ? null : (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-8"
              aria-label="Close"
              onClick={() => p.onOpenChange(false)}
            >
              <X className="size-4" />
            </Button>
          )}
        </div>
        {/* Scrolling body — the only scroll container. */}
        <div className="min-h-0 flex-1 overflow-auto px-5 py-4">
          {p.children as ReactNode}
        </div>
        {p.footer ? (
          <div className="flex flex-none items-center justify-end gap-2 border-t px-5 py-3">
            {p.footer as ReactNode}
          </div>
        ) : null}
        {resizable && !fullscreen ? (
          // The corner it resizes, drawn quietly; it speaks up on hover or keyboard focus.
          <div
            {...resizeHandleProps}
            data-testid="resize-handle"
            className="group absolute right-0 bottom-0 z-10 size-[18px] touch-none cursor-nwse-resize outline-none"
          >
            <span className="absolute right-[3px] bottom-[3px] size-2 border-r-2 border-b-2 border-border transition-[width,height,border-color] duration-150 group-hover:size-2.5 group-hover:border-r-[3px] group-hover:border-b-[3px] group-hover:border-primary group-focus:size-2.5 group-focus:border-r-[3px] group-focus:border-b-[3px] group-focus:border-primary" />
          </div>
        ) : null}
      </DialogContent>
    </Dialog>
  );
}

export function ShadDrawer(p: DrawerProps): ReactElement {
  const resizable = p.resizable ?? true;
  const atEnd = p.position !== "start";
  const presetW = SHEET_WIDTH[p.size ?? "medium"];
  const maxW =
    typeof window === "undefined"
      ? undefined
      : Math.max(320, window.innerWidth - 48);
  const { size, handleProps } = useResizable({
    axis: "x",
    min: { w: 320 },
    ...(maxW !== undefined ? { max: { w: maxW } } : {}),
    initial: { w: presetW },
    invertX: atEnd,
    label: "Resize panel",
  });
  const width = resizable ? (size.w ?? presetW) : presetW;

  // The built-in close button sits at absolute top-4 right-4. With our custom header
  // that sits at py-3 px-5, the close button overlaps the title text. When the close
  // button is shown (non-blocking), add pr-12 to the header to reserve space.
  const showCloseButton = !p.blocking;
  const headerPrClass = showCloseButton ? "pr-12" : "pr-5";

  return (
    <Sheet
      open={p.open}
      onOpenChange={(o) => {
        if (!o && p.blocking) return;
        p.onOpenChange(o);
      }}
    >
      <SheetContent
        side={atEnd ? "right" : "left"}
        showCloseButton={showCloseButton}
        aria-describedby={undefined}
        className="speel-shadcn flex flex-col gap-0 p-0 sm:max-w-none"
        style={{ width: `${width}px`, maxWidth: "96vw" }}
        onInteractOutside={(e) => {
          if (p.blocking) e.preventDefault();
        }}
        onEscapeKeyDown={(e) => {
          if (p.blocking) e.preventDefault();
        }}
      >
        <div
          className={cn(
            "flex flex-none items-center gap-2 border-b pl-5 py-3",
            headerPrClass,
          )}
        >
          <SheetTitle className="grow truncate text-lg font-semibold">
            {p.title ?? ""}
          </SheetTitle>
        </div>
        <div className="min-h-0 flex-1 overflow-auto px-5 py-4">
          {p.children as ReactNode}
        </div>
        {p.footer ? (
          <div className="flex flex-none items-center justify-end gap-2 border-t px-5 py-3">
            {p.footer as ReactNode}
          </div>
        ) : null}
        {resizable ? (
          // Grab target wider than the rule it draws; the rule itself only speaks up
          // on hover or keyboard focus.
          <div
            {...handleProps}
            data-testid="resize-handle"
            className={cn(
              "group absolute top-0 bottom-0 z-10 flex w-2.5 touch-none cursor-ew-resize justify-center outline-none",
              atEnd ? "left-0" : "right-0",
            )}
          >
            <span className="w-px bg-border transition-[width,background-color] duration-150 group-hover:w-[3px] group-hover:bg-primary group-focus:w-[3px] group-focus:bg-primary" />
          </div>
        ) : null}
      </SheetContent>
    </Sheet>
  );
}

export function ShadPopover(p: PopoverProps): ReactElement {
  return (
    <Popover open={p.open} onOpenChange={p.onOpenChange}>
      <PopoverTrigger asChild>
        <span className="inline-flex">{p.trigger as ReactNode}</span>
      </PopoverTrigger>
      <PopoverContent align="start" className="speel-shadcn w-auto min-w-60">
        {p.children as ReactNode}
      </PopoverContent>
    </Popover>
  );
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import type { KeyboardEvent, MouseEvent, ReactElement, ReactNode } from "react";
import { ArrowDown, ArrowUp } from "lucide-react";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from "@/lib/utils";

import {
  MIN_RESIZE_WIDTH,
  headerFloor,
  resolveColumnWidths,
  setOverflowTitle,
  textMeasurer,
  toFlexColumn,
  useContainerWidth,
  useResizable,
} from "@speel/react";
import type {
  HeaderRoom,
  RowIntent,
  TableColumn,
  TableProps,
  TableSort,
} from "@speel/react";

import { ShadIconButton } from "./fields";
import { ShadPopover } from "./overlays";

/** Tailwind's default spacing unit (`--spacing: 0.25rem`), used until the theme's is measured. */
const DEFAULT_SPACING = 4;

/**
 * The cell padding and header room this skin's markup takes, for a theme spacing unit of
 * `spacing` pixels. Every size involved is a Tailwind spacing multiple, so a density theme
 * that changes `--spacing` scales them all:
 * - padding: th `px-2` / td `p-2` — 2 units a side;
 * - label: the sort label's `px-1.5`;
 * - sortArrow: the `size-3.5` arrow and the `gap-1` before it;
 * - filterButton: `ShadIconButton`'s `size-8` and the `gap-1` before it.
 */
export function shadMetrics(spacing: number): {
  padding: number;
  room: HeaderRoom;
} {
  return {
    padding: 4 * spacing,
    room: {
      label: 3 * spacing,
      sortArrow: 4.5 * spacing,
      filterButton: 9 * spacing,
    },
  };
}

/** What the layout reads from the rendered table: the theme's spacing unit and header font. */
interface ShadTheme {
  spacing: number;
  /** CSS font shorthand the header labels render in. */
  font: string;
  fontSize: number;
}

/** `text-sm font-medium` at Tailwind's defaults, until the header is rendered to read. */
const DEFAULT_THEME: ShadTheme = {
  spacing: DEFAULT_SPACING,
  font: "500 14px sans-serif",
  fontSize: 14,
};

/**
 * Spacing units in the probe. Layout snaps a box to 1/64px, so the probe is ten units wide
 * rather than one: 0.2rem reads as 3.2, not 3.1875.
 */
const PROBE_UNITS = 10;

/** Reads the spacing unit off the probe (`w-10`) and the header font off a header cell. */
function readTheme(box: HTMLElement, probe?: HTMLElement): ShadTheme {
  const unit = (probe?.getBoundingClientRect().width ?? 0) / PROBE_UNITS;
  const spacing = Number.isFinite(unit) && unit > 0 ? unit : DEFAULT_SPACING;
  const th = box.querySelector("th");
  const style = th ? getComputedStyle(th) : undefined;
  const size = parseFloat(style?.fontSize ?? "");
  if (style && size > 0 && style.fontFamily)
    return {
      spacing,
      font: `${style.fontWeight || "500"} ${size}px ${style.fontFamily}`,
      fontSize: size,
    };
  const family = getComputedStyle(box).fontFamily || "sans-serif";
  return { spacing, font: `500 14px ${family}`, fontSize: 14 };
}

/** A column's `align`, as logical text alignment (start and end follow the writing direction). */
const ALIGN = {
  start: "text-start",
  center: "text-center",
  end: "text-end",
} as const;

function HeaderCell({
  column,
  sort,
  onSortChange,
}: {
  column: TableColumn;
  sort?: TableSort;
  onSortChange?: (key: string) => void;
}): ReactElement {
  const [filterOpen, setFilterOpen] = useState(false);
  const sorted = sort?.key === column.key;
  const arrow = "inline size-3.5 align-middle";
  return (
    <span className="flex w-full items-start gap-1">
      {/* The label box takes what the filter button leaves. It breaks a label only at spaces;
          a word wider than the box ends in "…" (text-overflow applies to every line). Its
          py-1 levels the first line with the filter button and keeps the sort label's
          hover and focus boxes inside the clip. */}
      <span
        data-header-label=""
        className={cn(
          "min-w-0 flex-1 overflow-hidden py-1 text-ellipsis whitespace-normal [overflow-wrap:normal] [word-break:normal]",
          column.align ? ALIGN[column.align] : undefined,
        )}
      >
        {column.headerContent !== undefined ? (
          // A control in the header owns its clicks: it is never wrapped in the sort button.
          (column.headerContent as ReactNode)
        ) : column.sortable && onSortChange ? (
          // A span, not a <button>: a button lays out as one inline-block whatever its
          // `display`, so a wrapped label would be a single box the ellipsis hides whole.
          // Inline, each line is its own fragment, and its own rounded hover/focus box.
          <span
            role="button"
            tabIndex={0}
            className="hover:bg-accent focus-visible:ring-ring inline cursor-pointer rounded px-1.5 py-0.5 outline-none box-decoration-clone focus-visible:ring-2 focus-visible:ring-inset"
            aria-label={
              sorted
                ? `${column.header}, sorted ${sort!.direction === "asc" ? "ascending" : "descending"}`
                : `${column.header}, sortable`
            }
            onClick={() => onSortChange(column.key)}
            onKeyDown={(e: KeyboardEvent<HTMLSpanElement>) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onSortChange(column.key);
              }
            }}
          >
            <span title={column.header}>{column.header}</span>
            {/* The arrow only on the sorted column, as in the v8 skin: inline with a label
                that wraps, an invisible hover hint could hold a line of its own. An ordinary
                space before it: a last word that fits, but not with the arrow, keeps its
                line and the arrow takes the next. */}
            {sorted ? (
              <>
                {" "}
                {sort!.direction === "asc" ? (
                  <ArrowUp className={arrow} />
                ) : (
                  <ArrowDown className={arrow} />
                )}
              </>
            ) : null}
          </span>
        ) : (
          <span title={column.header}>{column.header}</span>
        )}
      </span>
      {column.headerFilter ? (
        <span className="shrink-0">
          <ShadPopover
            open={filterOpen}
            onOpenChange={setFilterOpen}
            trigger={
              <ShadIconButton
                iconName="Filter"
                title={`Filter ${column.header}`}
                toggled={column.headerFilter.active}
                onClick={() => setFilterOpen((o) => !o)}
              />
            }
          >
            {column.headerFilter.content as ReactNode}
          </ShadPopover>
        </span>
      ) : null}
    </span>
  );
}

/**
 * A column's drag handle. It starts from the column's laid-out width and is held to the
 * column's own `minWidth`/`maxWidth`, so every width it reports is one the layout honours.
 *
 * The host is expected to echo each report straight back as the column's width — SpeelTable
 * does, synchronously, on every move of a drag — and the grip carries on through the echo.
 * When the layout puts the column anywhere the grip is not — the container resizes, another
 * column is dragged — the grip restarts from there. Restarting on an echo would end the drag
 * after its first step (and drop keyboard focus); a host that applies widths later, or not
 * at all, simply leaves the grip where the user left it until the layout next moves.
 */
function ResizeHandle({
  columnKey,
  width,
  minWidth,
  maxWidth,
  onColumnResize,
}: {
  columnKey: string;
  /** The column's laid-out content width. */
  width: number;
  minWidth: number | undefined;
  maxWidth: number | undefined;
  onColumnResize: (key: string, width: number) => void;
}): ReactElement {
  // The width the grip is at: where it started, or the last width it reported.
  const at = useRef(width);
  // Restarts count up, so a restart to the width the grip started from still restarts it.
  const [start, setStart] = useState({ width, restarts: 0 });
  useLayoutEffect(() => {
    // Within a pixel: a host may round what it is told.
    if (Math.abs(width - at.current) < 1) return;
    at.current = width;
    setStart((s) => ({ width, restarts: s.restarts + 1 }));
  }, [width]);
  const onResize = useCallback(
    (w: number) => {
      at.current = w;
      onColumnResize(columnKey, w);
    },
    [columnKey, onColumnResize],
  );
  // CSS order: a minimum beats a maximum.
  const min = Math.max(MIN_RESIZE_WIDTH, minWidth ?? 0);
  return (
    <ResizeGrip
      key={start.restarts}
      columnKey={columnKey}
      initial={start.width}
      min={min}
      {...(maxWidth !== undefined ? { max: Math.max(maxWidth, min) } : {})}
      onResize={onResize}
    />
  );
}

function ResizeGrip({
  columnKey,
  initial,
  min,
  max,
  onResize,
}: {
  columnKey: string;
  initial: number;
  min: number;
  max?: number;
  onResize: (width: number) => void;
}): ReactElement {
  const { size, handleProps } = useResizable({
    axis: "x",
    min: { w: min },
    ...(max !== undefined ? { max: { w: max } } : {}),
    initial: { w: initial },
  });
  // Only the user's drags report: the width the grip mounted with is the layout's.
  const mounted = useRef(initial);
  useEffect(() => {
    if (size.w !== undefined && size.w !== mounted.current) {
      mounted.current = size.w;
      onResize(size.w);
    }
  }, [size.w, onResize]);
  return (
    <span
      {...handleProps}
      role="separator"
      aria-orientation="vertical"
      aria-label={`Resize ${columnKey}`}
      className="hover:bg-border absolute top-0 right-0 h-full w-1 cursor-col-resize select-none"
    />
  );
}

const INTENT_ROW: Record<RowIntent, string> = {
  success: "bg-emerald-50 dark:bg-emerald-950/40",
  warning: "bg-amber-50 dark:bg-amber-950/40",
  error: "bg-destructive/10",
  muted: "text-muted-foreground bg-muted/40",
};

export function ShadTable(p: TableProps): ReactElement {
  // Hooks sit before the empty early-return: they may not be conditional.
  const container = useRef<HTMLDivElement>(null);
  const probe = useRef<HTMLSpanElement>(null);
  // What a percentage bound is a percentage of. The empty state renders the same div, so
  // React keeps the measured element when rows arrive.
  const containerWidth = useContainerWidth(container);
  const [theme, setTheme] = useState<ShadTheme>(DEFAULT_THEME);
  const hasRows = p.items.length > 0;
  // Read again whenever the container's width changes: a table that mounted hidden (a
  // collapsed tab or section) measures nothing until it is shown.
  useLayoutEffect(() => {
    if (!hasRows || !container.current) return;
    const next = readTheme(container.current, probe.current ?? undefined);
    setTheme((prev) =>
      prev.spacing === next.spacing &&
      prev.font === next.font &&
      prev.fontSize === next.fontSize
        ? prev
        : next,
    );
  }, [hasRows, containerWidth]);

  if (!hasRows) {
    return (
      <div ref={container} className="text-muted-foreground py-4 text-sm">
        {p.emptyMessage ?? "No items."}
      </div>
    );
  }
  const metrics = shadMetrics(theme.spacing);
  const room = metrics.room;
  // Whole pixels, like the widths: a fractional padding would leave the columns' total a
  // fraction off the table's width, and a table that fills its container would scroll by it.
  const padding = Math.round(metrics.padding);
  const measure = textMeasurer(theme.font, theme.fontSize);
  const layout = resolveColumnWidths(
    p.columns.map((c) =>
      toFlexColumn(
        c,
        headerFloor(
          c,
          c.sortable === true &&
            p.onSortChange !== undefined &&
            c.headerContent === undefined,
          measure,
          room,
        ),
        padding,
      ),
    ),
    {
      ...(p.minWidth !== undefined ? { minWidth: p.minWidth } : {}),
      ...(p.width !== undefined ? { width: p.width } : {}),
      ...(p.maxWidth !== undefined ? { maxWidth: p.maxWidth } : {}),
    },
    containerWidth,
  );
  // The columns' total, never `layout.tableWidth`: a fixed-layout table spreads any width
  // beyond its columns over them, so a table held to a bound nothing can grow into would
  // widen every column past its resolved width, and a dragged column would not land where
  // it was let go. Spare width stays empty instead, as in CSS flexbox and the v8 skin.
  const tableWidth = layout.widths.reduce((sum, w) => sum + w + padding, 0);
  return (
    // grid grid-cols-1 (= minmax(0,1fr)) caps the table width inside flex/grid
    // parents (e.g. the SharePoint canvas section) whose default min-width:auto
    // would otherwise let the table inflate its own container and defeat the
    // overflow-x-auto scroll. It is also the box measured for the layout.
    <div ref={container} className="grid grid-cols-1">
      {/* PROBE_UNITS spacing units wide: how the theme's density is read. */}
      <span ref={probe} aria-hidden className="invisible absolute w-10" />
      {/* Fixed layout: the columns are exactly the resolved widths, whatever their content. */}
      <Table style={{ tableLayout: "fixed", width: tableWidth }}>
        <colgroup>
          {p.columns.map((c, i) => (
            <col key={c.key} style={{ width: layout.widths[i]! + padding }} />
          ))}
        </colgroup>
        <TableHeader>
          <TableRow>
            {p.columns.map((c, i) => (
              // The primitive's h-10 stays: a table cell's height is a minimum, so a wrapped
              // label still grows the row, and one-line labels keep their height and centring.
              <TableHead key={c.key} className="relative whitespace-normal">
                <HeaderCell
                  column={c}
                  sort={p.sort}
                  onSortChange={p.onSortChange}
                />
                {p.onColumnResize ? (
                  <ResizeHandle
                    columnKey={c.key}
                    width={layout.widths[i]!}
                    minWidth={c.minWidth}
                    maxWidth={c.maxWidth}
                    onColumnResize={p.onColumnResize}
                  />
                ) : null}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {p.items.map((row, i) => {
            const intent = p.getRowIntent?.(row, i);
            const cls = p.getRowClassName?.(row, i);
            return (
              <TableRow
                key={p.getRowKey ? p.getRowKey(row, i) : i}
                className={cn(intent ? INTENT_ROW[intent] : undefined, cls)}
              >
                {p.columns.map((c) => (
                  <TableCell
                    key={c.key}
                    className={cn(
                      c.wrap
                        ? "overflow-hidden text-ellipsis whitespace-normal [overflow-wrap:normal] [word-break:normal]"
                        : "truncate",
                      c.align ? ALIGN[c.align] : undefined,
                    )}
                    {...(c.cellTitle
                      ? {
                          onMouseEnter: (e: MouseEvent<HTMLTableCellElement>) =>
                            setOverflowTitle(e.currentTarget, () =>
                              c.cellTitle!(row),
                            ),
                        }
                      : {})}
                  >
                    {c.render(row) as ReactNode}
                  </TableCell>
                ))}
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
}
